import{_ as a,a0 as n,w as p,s as r,ao as l,I as o,x as e,a1 as i,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux 中退出码的含义 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中退出码的含义 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中退出码的含义 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中退出码的含义 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230709.0 ⭐️⭐️ What are Exit Codes in Linux","title":"Linux 中退出码的含义","tag":"202308","desc":""},"relativePath":"202308/20230709.0 ⭐️⭐️ What are Exit Codes in Linux.md","filePath":"[post].md"}'),c={name:"202308/20230709.0 ⭐️⭐️ What are Exit Codes in Linux.md"};function g(m,t,u,h,f,x){const s=n("Link");return p(),r("div",null,[t[44]||(t[44]=l('<h1 id="linux-中退出码的含义" tabindex="-1">Linux 中退出码的含义 <a class="header-anchor" href="#linux-中退出码的含义" aria-label="Permalink to “Linux 中退出码的含义”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/03/154628oloxp7sl6s1z4pbl.jpg" alt=""></p><blockquote><p>揭开 Linux 中退出码的神秘面纱。了解什么是退出码，以及为什么和如何使用它们。</p></blockquote><p>退出码（退出状态）可以告诉我们最后一次执行的命令的状态。在命令结束以后，我们可以知道命令是成功完成的还是以错误结束的。</p><p><strong>其基本思想是，程序返回退出代码 <code>0</code> 时表示执行成功，没有问题。代码 <code>1</code> 或 <code>0</code> 以外的任何代码都被视为不成功。</strong></p><p>退出码除了 0 和 1 外还有很多值，我将在本文介绍它们。</p><h3 id="linux-shell-中的各种退出码" tabindex="-1">Linux Shell 中的各种退出码 <a class="header-anchor" href="#linux-shell-中的各种退出码" aria-label="Permalink to “Linux Shell 中的各种退出码”">​</a></h3><p>我们来快速了解一下 Linux Shell 中的主要退出码：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">退出码</th><th style="text-align:left;">解释</th></tr></thead><tbody><tr><td style="text-align:left;"><code>0</code></td><td style="text-align:left;">命令成功执行</td></tr><tr><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">通用错误代码</td></tr><tr><td style="text-align:left;"><code>2</code></td><td style="text-align:left;">命令（或参数）使用不当</td></tr><tr><td style="text-align:left;"><code>126</code></td><td style="text-align:left;">权限被拒绝（或）无法执行</td></tr><tr><td style="text-align:left;"><code>127</code></td><td style="text-align:left;">未找到命令，或 <code>PATH</code> 错误</td></tr><tr><td style="text-align:left;"><code>128+n</code></td><td style="text-align:left;">命令被信号从外部终止，或遇到致命错误</td></tr><tr><td style="text-align:left;"><code>130</code></td><td style="text-align:left;">通过 <code>Ctrl+C</code> 或 <code>SIGINT</code> 终止（<em>终止代码 2 或键盘中断</em>）</td></tr><tr><td style="text-align:left;"><code>143</code></td><td style="text-align:left;">通过 <code>SIGTERM</code> 终止（<em>默认终止</em>）</td></tr><tr><td style="text-align:left;"><code>255/*</code></td><td style="text-align:left;">退出码超过了 0-255 的范围，因此重新计算（LCTT 译注：超过 255 后，用退出码对 256 取模）</td></tr></tbody></table></div><blockquote><p>📋 <code>130</code>（<code>SIGINT</code> 或 <code>^C</code>）和 <code>143</code>（<code>SIGTERM</code>）等终止信号是非常典型的，它们属于 <code>128+n</code> 信号，其中 <code>n</code> 代表终止码。</p></blockquote><p>在简单了解了退出码之后，我们来看看它们的用法。</p><h3 id="获取退出码" tabindex="-1">获取退出码 <a class="header-anchor" href="#获取退出码" aria-label="Permalink to “获取退出码”">​</a></h3>',12)),o("p",null,[t[1]||(t[1]=e("前一个命令执行的退出码存储在 ",-1)),i(s,{href:"https://linuxhandbook.com:443/bash-special-variables/"},{default:d(()=>[...t[0]||(t[0]=[e("特殊变量",-1)])]),_:1}),t[2]||(t[2]=e()),t[3]||(t[3]=o("code",null,"$?",-1)),t[4]||(t[4]=e(" 中。你可以通过运行以下命令来获取：",-1))]),t[45]||(t[45]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $?</span></span></code></pre></div><p>我们在所有演示中都将使用它来获取退出代码。</p><p>请注意，<code>exit</code> 命令支持以带着前一条命令相同的退出码退出。</p><h3 id="退出码-0" tabindex="-1">退出码 0 <a class="header-anchor" href="#退出码-0" aria-label="Permalink to “退出码 0”">​</a></h3><p>退出码 <code>0</code> 表示命令执行无误，这是完成命令的理想状态。</p><p>例如，我们运行这样一条基本命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>neofetch </span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo $?</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_0.png" alt=""></p><p>这个退出码 <code>0</code> 表示特定命令已成功执行，仅此而已。让我们再演示几个例子。</p>`,9)),o("p",null,[t[6]||(t[6]=e("你可以尝试 ",-1)),i(s,{href:"https://itsfoss.com/how-to-find-the-process-id-of-a-program-and-kill-it-quick-tip/"},{default:d(()=>[...t[5]||(t[5]=[e("终止一个进程",-1)])]),_:1}),t[7]||(t[7]=e("；它也会返回代码 ",-1)),t[8]||(t[8]=o("code",null,"0",-1)),t[9]||(t[9]=e("。",-1))]),t[46]||(t[46]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pkill lxappearance</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_0.gif" alt=""></p><p>查看文件内容也会返回退出码 0，这<strong>仅</strong>意味着 <code>cat</code> 命令执行成功。</p><h3 id="退出码-1" tabindex="-1">退出码 1 <a class="header-anchor" href="#退出码-1" aria-label="Permalink to “退出码 1”">​</a></h3><p>退出码 <code>1</code> 也很常见。它通常表示命令以一般错误结束。</p>',5)),o("p",null,[t[11]||(t[11]=e("例如，在没有 sudo 权限的情况下使用 ",-1)),i(s,{href:"https://itsfoss.com/package-manager/"},{default:d(()=>[...t[10]||(t[10]=[e("软件包管理器",-1)])]),_:1}),t[12]||(t[12]=e("，就会返回代码 ",-1)),t[13]||(t[13]=o("code",null,"1",-1)),t[14]||(t[14]=e("。在 Arch Linux 中，如果我运行下面的命令：",-1))]),t[47]||(t[47]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Sy</span></span></code></pre></div><p>它会返回 <code>1</code>， 表示上一条命令运行出错。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_1.png" alt="exit code 1 (impermissible operation resulted in this code)"></p><blockquote><p>📋 如果你在基于 Ubuntu 的发行版中尝试这样做（不使用 <code>sudo</code> 执行 <code>apt update</code>），运行后会得到错误码 <code>100</code>，表示你是在没有权限的情况下运行 <code>apt</code>。<code>100</code> 不是标准错误码，而是 <code>apt</code> 特有的错误码。</p></blockquote><p>虽然这是一般的理解，但我们也可以将其解释为 “不被允许的操作”。</p><p>除以 <code>0</code> 等操作也会返回错误码 <code>1</code>。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_1-division_by_0-.png" alt="Division by zero results in code 1"></p><h3 id="退出码-2" tabindex="-1">退出码 2 <a class="header-anchor" href="#退出码-2" aria-label="Permalink to “退出码 2”">​</a></h3><p>这个退出码出现在当执行的命令有语法错误时。滥用命令参数也会导致此错误。</p><p>一般来说，它表示由于使用不当，命令无法执行。</p><p>例如，我在一个本应只有一个连字符的选项上添加了两个连字符，那么此时会出现退出码 2。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grep --z file.txt</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/exit_status_2-misusing_arguments--1.png" alt="Invalid argument resulted in exit code 2"></p><p>当权限被拒绝时，比如访问 <code>/root</code> 文件夹，就会出现错误码 <code>2</code>。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_2-permission_denied-.png" alt="Permission denied gives out code 2"></p><h3 id="退出码-126" tabindex="-1">退出码 126 <a class="header-anchor" href="#退出码-126" aria-label="Permalink to “退出码 126”">​</a></h3><p>126 是一个特殊的退出码，它用于表示命令或脚本因权限错误而未被执行。</p><p>当你尝试执行没有执行权限的 Shell 脚本时，就会出现这个错误。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_126.png" alt=""></p><p>请注意，该退出码只出现在没有足够权限的脚本或命令的“<em>执行</em>”中，这与一般的<strong>权限被拒绝</strong>错误不同。</p><p>因此，不要把它与你之前看到的退出码为 <code>2</code> 的示例混淆。在那个示例中，运行的是 <code>ls</code> 命令，权限问题出自它试图执行的目录。而本例中权限问题来自脚本本身。</p><h3 id="退出码-127" tabindex="-1">退出码 127 <a class="header-anchor" href="#退出码-127" aria-label="Permalink to “退出码 127”">​</a></h3>',22)),o("p",null,[t[16]||(t[16]=e("这是另一个常见的退出码。退出码 ",-1)),t[17]||(t[17]=o("code",null,"127",-1)),t[18]||(t[18]=e(" 指的是“",-1)),i(s,{href:"https://itsfoss.com/bash-command-not-found/"},{default:d(()=>[...t[15]||(t[15]=[e("未找到命令",-1)])]),_:1}),t[19]||(t[19]=e("”。它通常发生在执行的命令有错别字或所需的可执行文件不在 ",-1)),t[20]||(t[20]=o("code",null,"$PATH",-1)),t[21]||(t[21]=e(" 变量中时。",-1))]),t[48]||(t[48]=o("p",null,"例如，当我尝试执行一个不带路径的脚本时，经常会看到这个错误。",-1)),t[49]||(t[49]=o("p",null,[o("img",{src:"https://itsfoss.com/content/images/2023/06/exit_code_127.png",alt:'Script executed without the path gives "command not found" or code 127'})],-1)),o("p",null,[t[23]||(t[23]=e("当你想运行的可执行文件不在 ",-1)),t[24]||(t[24]=o("code",null,"$PATH",-1)),t[25]||(t[25]=e(" 变量中时，也会出现退出码 ",-1)),t[26]||(t[26]=o("code",null,"127",-1)),t[27]||(t[27]=e("。你可以通过 ",-1)),i(s,{href:"https://itsfoss.com/add-directory-to-path-linux/"},{default:d(()=>[...t[22]||(t[22]=[e("在 PATH 变量中添加命令的目录",-1)])]),_:1}),t[28]||(t[28]=e(" 来纠正这种情况。",-1))]),t[50]||(t[50]=l('<p>当你输入不存在的命令时，也会得到这样的退出码。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_127-command_not_found--1.png" alt="Unmount is not a command, and Screenfetch is not installed, which resulted in code 127"></p><h3 id="退出码-128-n-系列" tabindex="-1">退出码 128+n 系列 <a class="header-anchor" href="#退出码-128-n-系列" aria-label="Permalink to “退出码 128+n 系列”">​</a></h3><p>当应用程序或命令因致命错误而终止或执行失败时，将产生 128 系列退出码（<code>128+n</code>），其中 <code>n</code> 为信号编号。</p><p><code>n</code> 包括所有类型的终止代码，如 <code>SIGTERM</code>、<code>SIGKILL</code> 等。</p><h4 id="退出码-130-或-sigint" tabindex="-1">退出码 130 或 SIGINT <a class="header-anchor" href="#退出码-130-或-sigint" aria-label="Permalink to “退出码 130 或 SIGINT”">​</a></h4><p>在通过终止信号 <code>2</code> 或按下 <code>Ctrl+C</code> 中断进程时，会发出 <code>SIGINT</code>（键盘中断信号）。</p><p>因为终止信号是 <code>2</code>，所以我们得到的退出码是 <code>130</code>（128+2）。下面的视频演示了 <code>lxappearance</code> 的中断信号。</p><p><img src="https://itsfoss.com/content/media/2023/06/exit_code_128-n-SIGINT-_compressed.mp4" alt=""></p><h4 id="退出码-137-或-sigkill" tabindex="-1">退出码 137 或 SIGKILL <a class="header-anchor" href="#退出码-137-或-sigkill" aria-label="Permalink to “退出码 137 或 SIGKILL”">​</a></h4><p><code>SIGKILL</code>（立即终止信号）表示终止信号 <code>9</code>。这是终止应用程序时最不应该使用的方法。</p><p>因为终止信号为 <code>9</code>，因此我们得到的退出代码为 <code>137</code>（128+9）。</p><p><img src="https://itsfoss.com/content/media/2023/06/exit_code_128-n-SIGKILL-_compressed.mp4" alt=""></p><h4 id="退出码-143-或-sigterm" tabindex="-1">退出码 143 或 SIGTERM <a class="header-anchor" href="#退出码-143-或-sigterm" aria-label="Permalink to “退出码 143 或 SIGTERM”">​</a></h4><p><code>SIGTERM</code> 是进程在未指定参数的情况下被杀死时的默认行为。</p><p><code>SIGTERM</code> 的终止信号为 <code>15</code>，因此该信号的退出码为 <code>143</code>（128+15）。</p><p><img src="https://itsfoss.com/content/media/2023/06/exit_code_128-n-SIGTERM-_compressed-1.mp4" alt=""></p><p>还有一些你以前可能不知道的终止信号，它们也有自己类似的退出码。你可以在这里查看它们：</p><blockquote><p>📋 请注意，如果进程在启动它的同一会话中终止，这些信号可能不会出现。如果要重现这些信号，请从不同的 shell 终止。</p><p>就个人而言，信号 <code>128</code> 是无法重现的。</p></blockquote><h3 id="当退出码超过了-255-会怎样" tabindex="-1">当退出码超过了 255 会怎样? <a class="header-anchor" href="#当退出码超过了-255-会怎样" aria-label="Permalink to “当退出码超过了 255 会怎样?”">​</a></h3><p>最新版本的 Bash 甚至保留了超过 255 的原始退出码的值，但一般来说，如果代码超过 255，就会被重新计算。</p><p>也就是说，代码 <code>256</code> 会变成 <code>0</code>，<code>257</code> 会变成 <code>1</code>，<code>383</code> 会变成 <code>127</code>，以此类推。为确保更好的兼容性，请将退出码保持在 <code>0</code> 至 <code>255</code> 之间。</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>希望你对 Linux Shell 中的退出码有所了解。在排查各种问题时，使用它们会非常方便。</p><p>如果你要在 Shell 脚本中使用这些代码，请确保你了解每个代码的含义，以便更容易地排除故障。</p><p>这就是本文的全部内容。如有遗漏，请在评论区告诉我。</p><p><em>（题图：MJ/719ff711-1b9f-4aa9-a82e-980704acbdd8）</em></p><hr>',28)),o("p",null,[t[30]||(t[30]=e("via: ",-1)),i(s,{href:"https://itsfoss.com/linux-exit-codes/"},{default:d(()=>[...t[29]||(t[29]=[e("https://itsfoss.com/linux-exit-codes/",-1)])]),_:1})]),o("p",null,[t[35]||(t[35]=e("作者：",-1)),i(s,{href:"https://itsfoss.com/author/pranav/"},{default:d(()=>[...t[31]||(t[31]=[e("Pranav Krishna",-1)])]),_:1}),t[36]||(t[36]=e(" 选题：",-1)),i(s,{href:"https://github.com/lkxed/"},{default:d(()=>[...t[32]||(t[32]=[e("lkxed",-1)])]),_:1}),t[37]||(t[37]=e(" 译者：",-1)),i(s,{href:"https://github.com/lxbwolf"},{default:d(()=>[...t[33]||(t[33]=[e("lxbwolf",-1)])]),_:1}),t[38]||(t[38]=e(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:d(()=>[...t[34]||(t[34]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[41]||(t[41]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[39]||(t[39]=[e("LCTT",-1)])]),_:1}),t[42]||(t[42]=e(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:d(()=>[...t[40]||(t[40]=[e("Linux中国",-1)])]),_:1}),t[43]||(t[43]=e(" 荣誉推出",-1))])])}const S=a(c,[["render",g]]);export{T as __pageData,S as default};
